#include <pybind11/pybind11.h>

#include <cstddef>
#include <utility>

// The bindings themselves live in the bind_part_<k>.cpp translation units
// generated by CMake (see py_bind_part.hpp); this one only creates the module.

#ifndef NONOS_PARTS
#error "NONOS_PARTS must be defined"
#endif

namespace siconos::python::disks {
template <std::size_t Part>
void bind_part(pybind11::module_& disks);
}  // namespace siconos::python::disks

PYBIND11_MODULE(_nonos, m) {
  // sub module disks
  auto disks = m.def_submodule("disks");

  disks.doc() = R"pbdoc(
        Nonos m
        -----------

        .. currentmodule:: nonos

        .. autosummary::
           :toctree: _generate

           add
           subtract
    )pbdoc";

  [&disks]<std::size_t... Part>(std::index_sequence<Part...>) {
    (siconos::python::disks::bind_part<Part>(disks), ...);
  }(std::make_index_sequence<NONOS_PARTS>{});

  disks.attr("__version__") = "dev";
  m.attr("__version__") = "dev";
}
